def longest_palindrome(s):

    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and (s[left] == s[right]):
            left -= 1
            right += 1
        return s[left + 1:right]
    if len(s) <= 2:
        return s
    max_len = 1
    max_palindrome = s[0]
    for i in range(len(s)):
        palindrome_odd = expand_around_center(i, i)
        palindrome_even = expand_around_center(i, i + 1)
        if len(palindrome_odd) > max_len:
            max_len = len(palindrome_odd)
            max_palindrome = palindrome_odd
        if len(palindrome_even) > max_len:
            max_len = len(palindrome_even)
            max_palindrome = palindrome_even
    return max_palindrome

def longest_palindrome(s):
    """
    Returns the longest substring of s that is a palindrome.

    :param s: The input string.
    :return: The longest substring of s that is a palindrome.
    """

    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and (s[left] == s[right]):
            left -= 1
            right += 1
        return s[left + 1:right]
    if not s:
        return ''
    longest = ''
    for i in range(len(s)):
        odd_palindrome = expand_around_center(s, i, i)
        even_palindrome = expand_around_center(s, i, i + 1)
        if len(odd_palindrome) > len(longest):
            longest = odd_palindrome
        if len(even_palindrome) > len(longest):
            longest = even_palindrome
    return longest

def longest_palindrome(s):

    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and (s[left] == s[right]):
            left -= 1
            right += 1
        return s[left + 1:right]
    max_length = 0
    start = 0
    for i in range(len(s)):
        odd_palindrome = expand_around_center(i, i)
        even_palindrome = expand_around_center(i, i + 1)
        if len(odd_palindrome) > max_length:
            max_length = len(odd_palindrome)
            start = i - (len(odd_palindrome) - 1) // 2
        if len(even_palindrome) > max_length:
            max_length = len(even_palindrome)
            start = i - (len(even_palindrome) - 1) // 2
    return s[start:start + max_length]

def longest_palindrome(s: str) -> str:

    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and (s[left] == s[right]):
            left -= 1
            right += 1
        return s[left + 1:right]
    max_length = 0
    start = 0
    for i in range(len(s)):
        odd_len = expand_around_center(i, i)
        even_len = expand_around_center(i, i + 1)
        if len(odd_len) > len(even_len):
            temp_start, temp_end = (i, i + len(odd_len))
            max_length = max(max_length, len(odd_len))
            start = min(start, temp_start)
        else:
            temp_start, temp_end = (i, i + 1 + len(even_len))
            max_length = max(max_length, len(even_len))
            start = min(start, temp_start)
    return s[start:start + max_length]

def roman_to_int(s):
    """
    Converts a Roman numeral to an integer.

    Parameters:
    s (str): A string representing a Roman numeral.

    Returns:
    int: The integer value of the Roman numeral.

    Raises:
    ValueError: If the input is not a valid Roman numeral.
    """
    if not s or len(s) == 0:
        raise ValueError('Input cannot be empty')
    roman_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i] in ['I', 'X', 'C'] and (s[i + 1] in ['V', 'L', 'D']):
            if (s[i:i + 2] == 'IV' or s[i:i + 2] == 'IX') and i + 2 < len(s):
                result += roman_numerals[s[i + 2]]
                i += 3
            elif (s[i:i + 2] == 'XL' or s[i:i + 2] == 'XC') and i + 2 < len(s):
                result += roman_numerals[s[i + 2]]
                i += 3
            elif (s[i:i + 2] == 'CD' or s[i:i + 2] == 'CM') and i + 2 < len(s):
                result += roman_numerals[s[i + 2]]
                i += 3
            else:
                raise ValueError('Invalid Roman numeral')
        else:
            if s[i] not in roman_numerals:
                raise ValueError('Invalid character in input')
            if roman_numerals[s[i]] != 0:
                result += roman_numerals[s[i]]
            i += 1
    return result

def roman_to_int(s):
    """
    Converts a Roman numeral to an integer.

    Args:
        s (str): A string representing a Roman numeral.

    Returns:
        int: The integer value of the Roman numeral.

    Raises:
        ValueError: If the input string is not a valid Roman numeral.
    """
    if not s:
        raise ValueError('Input string cannot be empty')
    roman_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if s[i] not in roman_numerals:
            raise ValueError('Invalid Roman numeral')
        if i < len(s) - 1 and roman_numerals[s[i]] < roman_numerals[s[i + 1]]:
            total -= roman_numerals[s[i]]
        else:
            total += roman_numerals[s[i]]
    return total

def roman_to_int(s: str) -> int:
    """
    Converts Roman numerals to integers.

    Parameters:
    s (str): The Roman numeral string.

    Returns:
    int: The integer value of the Roman numerals.

    Raises:
    ValueError: If the input contains invalid characters or formatting.
    """
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    if not s:
        raise ValueError('Input must be a non-empty string.')
    for i, char in enumerate(s):
        try:
            num = roman_map[char.upper()]
            if i > 0 and num > roman_map[s[i - 1].upper()]:
                raise ValueError('Invalid subtractive notation.')
            result += num
        except KeyError:
            raise ValueError(f"Invalid input: '{char}' is not a valid Roman numeral.")
    return result

def roman_to_int(s: str) -> int:
    """
    Convert a Roman numeral string into its integer value.

    Args:
        s (str): The Roman numeral string to convert.

    Returns:
        int: The integer value of the input Roman numeral string.

    Raises:
        ValueError: If the input is not valid, including incorrect subtractive notation or invalid repetitions.
    """
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    if not isinstance(s, str) or not all((c in roman_values for c in s)):
        raise ValueError('Invalid Roman numeral string')
    for i, char in enumerate(s):
        if i < len(s) - 1 and roman_values[char] < roman_values[s[i + 1]]:
            result -= roman_values[char]
        else:
            result += roman_values[char]
    if not 1 <= result <= 3999:
        raise ValueError('Invalid Roman numeral string')
    return result

def roman_to_int(s: str) -> int:
    if not s:
        raise ValueError('Invalid input')
    mapping = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    subtractive_pairs = ['IV', 'IX', 'XL', 'XC', 'CD', 'CM']
    valid_numerals = {'I': [True, False], 'X': [False, True, False], 'C': [False, False, True], 'M': [False, False, False]}
    i = 0
    while i < len(s):
        if s[i:i + 2] in subtractive_pairs:
            if s[i:i + 2] not in mapping or s[i + 1:i + 3] not in mapping:
                raise ValueError('Invalid numeral')
            result += mapping[s[i + 2]]
            i += 2
        elif s[i] in mapping:
            repetition_valid = valid_numerals.get(s[i], [False])[i % 4]
            if s[i] == 'V' or s[i] == 'L' or s[i] == 'D':
                repetition_valid = True
            if not repetition_valid and i > 0 and (s[i] <= s[i - 1]):
                raise ValueError('Invalid numeral')
            result += mapping[s[i]]
            i += 1
        else:
            raise ValueError('Invalid numeral')
    return result

def roman_to_int(s: str) -> int:
    if not s:
        raise ValueError('Input cannot be empty')
    mapping = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    subtractive_pairs = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}
    i = 0
    result = 0
    while i < len(s):
        if s[i] not in mapping:
            raise ValueError(f"Invalid symbol '{s[i]}' at position {i + 1}")
        value = mapping[s[i]]
        if i + 1 < len(s) and s[i:i + 2] in subtractive_pairs:
            result += value - 5 * mapping[s[i + 1]]
            i += 2
        else:
            result += value
            i += 1
            if s[i - 1] == 'I' and s[i - 3:i] == 'III':
                raise ValueError('Repeated I at position {} is invalid'.format(i))
            elif s[i - 1] == 'X' and s[i - 3:i] == 'XXX':
                raise ValueError('Repeated X at position {} is invalid'.format(i))
            elif s[i - 1] == 'C' and s[i - 3:i] == 'CCC':
                raise ValueError('Repeated C at position {} is invalid'.format(i))
            elif s[i - 1] == 'M' and s[i - 3:i] == 'MMM':
                raise ValueError('Repeated M at position {} is invalid'.format(i))
            if i < len(s) and s[i] in ['V', 'L', 'D'] and (s[i] == s[i - 1]):
                raise ValueError(f'Repeated {s[i]} at position {i + 1} is invalid')
    return result

def roman_to_int(s: str) -> int:
    if not s:
        raise ValueError('Invalid input')
    valid_symbols = 'IVXLCDM'
    if any((c not in valid_symbols for c in s)):
        raise ValueError('Invalid input')
    numeral_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i > 0 and numeral_values[s[i]] > numeral_values[s[i - 1]]:
            if s[i] == 'I' and s[i - 1] not in ['V', 'X'] or (s[i] == 'X' and s[i - 1] != 'C') or (s[i] == 'C' and s[i - 1] not in ['D', 'M']):
                raise ValueError('Invalid input')
            total += numeral_values[s[i]] - 2 * numeral_values[s[i - 1]]
        else:
            total += numeral_values[s[i]]
    if any((s[i] * (i + 1 < len(s) and s[i + 1] == s[i]) > 3 for i, c in enumerate(s) if 'IM' not in s and c in ['I', 'X', 'C'])):
        raise ValueError('Invalid input')
    if any((s.count(c) >= 2 for c in ['V', 'L', 'D'])):
        raise ValueError('Invalid input')
    return total

def is_balanced(s: str) -> bool:
    """
    Checks if the brackets in the string are balanced and properly nested.

    Args:
        s (str): The input string to check for bracket balance.

    Returns:
        bool: True if the brackets are balanced, False otherwise.
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    opening_brackets = []
    for char in s:
        if char in bracket_map.values():
            opening_brackets.append(char)
        elif char in bracket_map.keys():
            if not opening_brackets or opening_brackets.pop() != bracket_map[char]:
                return False
    return not opening_brackets

def is_balanced(s: str) -> bool:
    """
    Returns True if the brackets in the string are balanced and properly nested, False otherwise.

    :param s: input string to check for balanced brackets
    :return: boolean indicating whether brackets are balanced
    """
    bracket_map = {')': '(', '}': '{', ']': '['}
    opening_brackets = []
    for char in s:
        if not (char in bracket_map.keys() or char in ['(', '[', '{']):
            continue
        elif char in ['(', '[', '{']:
            opening_brackets.append(char)
        elif not opening_brackets or opening_brackets.pop() != bracket_map[char]:
            return False
    return not opening_brackets

def is_balanced(s: str) -> bool:
    """
    Return True if the brackets in the string are balanced and properly nested, 
    and False otherwise.

    :param s: Input string to check for bracket balance
    :return: bool indicating whether brackets are balanced
    """
    bracket_map = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in s:
        if char not in bracket_map and char not in ['(', '[', '{']:
            continue
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return not stack

