def is_balanced(s: str) -> bool:
    stack = []
    for c in s:
        if c in '({[':
            stack.append(c)
        elif c in ')}]':
            try:
                last_opening_bracket = stack.pop()
                opening_brackets_map = {'(': ')', '[': ']', '{': '}'}
                if opening_brackets_map[last_opening_bracket] != c:
                    return False
            except IndexError:
                return False
    return len(stack) == 0

import operator as op

def evaluate(expr: str) -> int:
    expr = expr.replace(' ', '')
    ops = {'+': op.add, '-': op.sub, '*': op.mul, '/': lambda a, b: a // b}
    stack = []
    op_stack = []
    for char in expr:
        if char.isdigit():
            stack.append(int(char))
        elif char in ops:
            while len(op_stack) > 0 and op_stack[-1] != '(' and (get_precedence(op_stack[-1]) >= get_precedence(char)):
                apply_op(stack, op_stack.pop(), ops)
            op_stack.append(char)
        elif char == '(':
            op_stack.append(char)
        elif char == ')':
            while len(op_stack) > 0 and op_stack[-1] != '(':
                apply_op(stack, op_stack.pop(), ops)
            if op_stack[-1] == '(':
                op_stack.pop()
    while len(op_stack) > 0:
        apply_op(stack, op_stack.pop(), ops)
    if len(stack) != 1:
        raise ValueError('Invalid expression')
    return stack[0]

def get_precedence(char):
    """Returns the precedence of an operator"""
    return {'+': 1, '-': 1, '*': 2, '/': 2}.get(char)

def apply_op(stack, op, ops):
    """Applies an operation with two operands on top of the stack"""
    b = stack.pop()
    a = stack.pop()
    if op == '(':
        stack.append(a)
        stack.append(b)
    else:
        result = ops[op](a, b)
        stack.append(result)

def evaluate(expr: str) -> int:
    """
    Evaluates an arithmetic expression and returns the integer result.

    Args:
        expr (str): The expression to evaluate, ignoring whitespace.

    Returns:
        int: The integer result of the evaluated expression.

    Raises:
        ValueError: If the expression is invalid.
    """
    operators = {'+': lambda x, y: x + y, '-': lambda x, y: x - y, '*': lambda x, y: x * y, '/': lambda x, y: int(x / y) if isinstance(x, int) and isinstance(y, int) else x / y}
    stack = []
    curr_expr = ''
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isdigit() or char == '.':
            curr_expr += char
        elif char in operators:
            if not stack:
                raise ValueError('Invalid expression: missing operand')
            num = int(curr_expr) if curr_expr else stack.pop()
            func = operators[char]
            if expr[i + 1] == '(':
                i += 2
                arg = evaluate(expr[i:])
                i = len(expr)
                num = func(num, arg)
            else:
                op = stack.pop()
                if isinstance(op, str):
                    raise ValueError('Invalid expression: unsupported operator')
                num = func(op, num)
            stack.append(num)
            curr_expr = ''
        elif char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                raise ValueError('Invalid expression: mismatched parentheses')
            while stack and isinstance(stack[-1], int) or (isinstance(stack[-1], str) and stack[-1] in operators):
                num = stack.pop()
                if isinstance(num, str):
                    func = operators[num]
                else:
                    func = lambda x, y: x + y
                op = stack.pop() if stack else 0
                num = func(op, num)
                stack.append(num)
        else:
            raise ValueError(f"Invalid expression: unexpected character '{char}'")
        i += 1
    while stack and isinstance(stack[-1], int) or (isinstance(stack[-1], str) and stack[-1] in operators):
        num = stack.pop()
        if isinstance(num, str):
            func = operators[num]
        else:
            func = lambda x, y: x + y
        op = stack.pop() if stack else 0
        num = func(op, num)
        stack.append(num)
    if stack and isinstance(stack[-1], int):
        raise ValueError('Invalid expression: unexpected trailing digits')
    return stack[0]

def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression string containing integers, +, -, *, /, and parentheses.

    Args:
        expr (str): The arithmetic expression to be evaluated.

    Returns:
        int: The integer result of the evaluation.
    """
    expr = expr.replace(' ', '')
    try:
        return int(eval(expr))
    except Exception as e:
        raise ValueError(f'Invalid arithmetic expression: {expr}. Error: {str(e)}')

def evaluate(expr: str) -> int:

    def apply_operator():
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        else:
            return left // right
    values, operators = ([], [])
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i].isdigit():
            j = i
            while i < len(expr) and expr[i].isdigit():
                i += 1
            values.append(int(expr[j:i]))
        elif expr[i] == '(':
            operators.append(expr[i])
            i += 1
        elif expr[i] in '+-*/':
            while operators and operators[-1] != '(' and (operators[-1] in '+-*/') and (expr[i] == '*' or operators[-1] == '/'):
                values.append(apply_operator())
            operators.append(expr[i])
            i += 1
        else:
            raise ValueError('Invalid character')
    while operators:
        values.append(apply_operator())
    if len(values) != 1:
        raise ValueError('Invalid expression')
    return values[0]

def evaluate(expr: str) -> int:

    def apply_operator():
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            return left // right

    def precedence(op):
        if op in {'+', '-'}:
            return 1
        if op in {'*', '/'}:
            return 2
        return 0
    i = 0
    num = ''
    values = []
    operators = []
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i].isdigit():
            while i < len(expr) and expr[i].isdigit():
                num += expr[i]
                i += 1
            values.append(int(num))
            num = ''
        elif expr[i] in {'+', '-', '*', '/'}:
            while operators and operators[-1] != '(' and (precedence(operators[-1]) >= precedence(expr[i])):
                apply_operator()
            operators.append(expr[i])
            i += 1
        elif expr[i] == '(':
            operators.append(expr[i])
            i += 1
        elif expr[i] == ')':
            while operators[-1] != '(':
                apply_operator()
            operators.pop()
            i += 1
    while operators:
        apply_operator()
    return values[0]

def evaluate(expr: str) -> int:

    def apply_op():
        op = ops.pop()
        if op == '+':
            return top() + bottom()
        elif op == '-':
            return top() - bottom()
        elif op == '*':
            return top() * bottom()
        else:
            return int(top() / bottom())

    def parse():
        nonlocal i
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i].isdigit():
                j = i
                while i < len(expr) and expr[i].isdigit():
                    i += 1
                yield int(expr[j:i])
            elif expr[i] in '+-*/':
                i += 1
                ops.append(expr[i - 1])
            elif expr[i] == '(':
                i += 1
                ops.append('(')
                for x in parse():
                    if isinstance(x, int):
                        stack.append(x)
                    else:
                        while ops[-1] != '(' and ops[-1] != ')':
                            apply_op()
                        if ops[-1] == '(':
                            ops.pop()
            elif expr[i] == ')':
                i += 1
                while ops[-1] != '(':
                    apply_op()
                ops.pop()

    def precedence(op):
        return {'+': 1, '-': 1, '*': 2, '/': 2}.get(op)
    stack = []
    ops = []
    i = 0
    for x in parse():
        if isinstance(x, int):
            stack.append(x)
        else:
            while ops and ops[-1] != '(' and (precedence(ops[-1]) >= precedence(x)):
                apply_op()
            ops.append(x)
    while ops:
        apply_op()
    return stack.pop()

def decode_string(s: str) -> str:
    stack = []
    curr_num = ''
    curr_str = ''
    for ch in s:
        if ch.isdigit():
            curr_num += ch
        elif ch == '[':
            stack.append(curr_str)
            stack.append(int(curr_num or 1))
            curr_str, curr_num = ('', '')
        elif ch == ']':
            num = stack.pop()
            prev_str = stack.pop()
            curr_str = prev_str + num * curr_str
        else:
            curr_str += ch
    return curr_str

def decode_string(s: str) -> str:

    def recursive_decode(s, cur_num):
        stack = []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                cur_num = int(s[i:j])
                i = j
            elif s[i] == '[':
                stack.append((cur_num, i))
                i += 1
            else:
                if not stack:
                    return ''
                num, start = stack.pop()
                end = i - 1
                result = recursive_decode(s[start + 1:end], cur_num) * num
                i = end + 1
        result = ''.join((recursive_decode('' + s[i], 0) for i in range(0, len(s), 2)))
        if not stack and result:
            return result
        else:
            raise ValueError('Invalid input')
    return recursive_decode(s, 0)

def decode_string(s: str) -> str:
    stack = []
    cur_num = ''
    cur_str = ''
    for c in s:
        if c.isdigit():
            cur_num += c
        elif c == '[':
            stack.append(cur_str)
            stack.append(int(cur_num))
            cur_str = ''
            cur_num = ''
        elif c == ']':
            num = stack.pop()
            prev_str = stack.pop()
            cur_str = prev_str + num * cur_str
        else:
            cur_str += c
    if stack:
        raise ValueError('Invalid input')
    return cur_str

def decode_string(s: str) -> str:
    stack = []
    cur_num = ''
    prev_char = ''
    cur_str = ''
    for c in s:
        if c.isdigit():
            cur_num += c
        elif c == '[':
            if cur_num != '':
                raise ValueError('Missing repeat count before brackets')
            stack.append(cur_str)
            stack.append(prev_char)
            cur_str, prev_char = ('', '')
        elif c == ']':
            if cur_num == '':
                raise ValueError('Mismatched brackets')
            num = int(cur_num)
            cur_str += num * prev_char
            cur_num, prev_char = ('', '')
            cur_str = stack.pop() + cur_str
            prev_char = stack.pop()
        else:
            if cur_num != '':
                cur_str += cur_num * c
                cur_num = ''
            cur_str += c
    if cur_num != '':
        raise ValueError('Mismatched brackets')
    return cur_str

def remove_k_digits(num: str, k: int) -> str:
    num = list(num)
    for i in range(k):
        found = False
        for j in range(len(num) - 1):
            if num[j] > num[j + 1]:
                num.pop(j)
                num.insert(j, '0')
                found = True
                break
        if not found:
            num.pop()
    while num and num[0] == '0':
        num.pop(0)
    return ''.join(num)

def remove_k_digits(num: str, k: int) -> str:
    stack = []
    for digit in num:
        while stack and k > 0 and (stack[-1] > digit):
            k -= 1
            stack.pop()
        stack.append(digit)
    while k > 0:
        stack.pop()
        k -= 1
    return ''.join(stack).lstrip('0') or '0'

def remove_k_digits(num: str, k: int) -> str:
    stack = []
    for n in num:
        while k > 0 and len(stack) > 0 and (stack[-1] > n):
            stack.pop()
            k -= 1
        stack.append(n)
    if k != 0:
        stack = stack[:-k]
    return '0' if not stack else ''.join(stack).lstrip('0') or '0'

def wildcard_match(s: str, p: str) -> bool:
    """
    Returns True if the entire string s matches the wildcard pattern p, otherwise returns False.

    Rules:
    - '?' matches exactly one character
    - '*' matches any sequence of characters, including the empty sequence
    - Matching must cover the entire string

    :param s: The input string to match.
    :param p: The wildcard pattern to match against.
    :return: True if the string matches the pattern, False otherwise.
    """
    if not s and (not p):
        return True
    if p and p[0] == '*':
        return wildcard_match(s, p[1:]) or (s and wildcard_match(s[1:], p))
    if p and len(p) > 0 and (len(s) > 0) and (p[0] != s[0] and p[0] != '?'):
        return False
    if p and len(p) > 0 and (p[0] == s[0] or p[0] == '?'):
        return wildcard_match(s[1:], p[1:])
    return False

def wildcard_match(s: str, p: str) -> bool:
    """
    Returns True if the entire string s matches the wildcard pattern p, otherwise returns False.

    Rules:
    - '?' matches exactly one character
    - '*' matches any sequence of characters, including the empty sequence
    - Matching must cover the entire string

    :param s: The input string to match against the pattern.
    :type s: str
    :param p: The wildcard pattern to match against the string.
    :type p: str
    :return: True if the string matches the pattern, False otherwise.
    """
    if len(s) == 0:
        for i in range(len(p)):
            if p[i] != '*':
                return False
        return True
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True
    for i in range(1, len(p) + 1):
        if p[i - 1] == '*':
            dp[0][i] = dp[0][i - 1]
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            else:
                dp[i][j] = p[j - 1] == s[i - 1] and dp[i - 1][j - 1]
    return dp[len(s)][len(p)]

def wildcard_match(s: str, p: str) -> bool:
    """
    Return True if the entire string s matches the wildcard pattern p, otherwise return False.

    Rules:
    - '?' matches exactly one character
    - '*' matches any sequence of characters, including the empty sequence
    - Matching must cover the entire string
    """
    if len(p) == 0 and len(s) > 0:
        return False
    if len(p) == 0 and len(s) != 0:
        return False
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif p[j - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] and s[i - 1] == p[j - 1]
    return dp[len(s)][len(p)]

def wildcard_match(s: str, p: str) -> bool:
    """
    Check whether a string matches a wildcard pattern.

    Args:
        s (str): The input string.
        p (str): The wildcard pattern.

    Returns:
        bool: True if the string matches the pattern, False otherwise.
    """
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
