def word_frequency(text):
    """
    Calculate the frequency of each word in a given text.

    Args:
        text (str): The input text.

    Returns:
        dict: A dictionary where keys are unique words and values are their frequencies.
    """
    words = text.split()
    freq_dict = {}
    for word in words:
        if word in freq_dict:
            freq_dict[word] += 1
        else:
            freq_dict[word] = 1
    return freq_dict

import re

def word_frequency(text):
    """
    Returns a dictionary with word frequencies in the given text.

    :param text: The input text.
    :return: A dictionary where keys are words and values are their frequencies.
    """
    text = re.sub('\\s+', ' ', text).lower()
    words = text.split()
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

import re

def word_frequency(text):
    """
    Returns a dictionary where keys are unique words and values are their frequencies.

    :param text: The input string to be processed
    :return: A dictionary with word frequencies
    """
    words = re.findall('\\b\\w+\\b', text.lower())
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last_merged = merged[-1]
        if current[0] <= last_merged[1]:
            merged[-1] = (last_merged[0], max(last_merged[1], current[1]))
        else:
            merged.append(current)
    return merged

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return merged

def longest_palindrome(s):
    if not s or len(s) == 1:
        return s
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    max_length = 0
    start = 0
    for i in range(n):
        dp[i][i] = True
    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            if s[i] == s[j] and dp[i + 1][j - 1]:
                dp[i][j] = True
                if L > max_length:
                    start, max_length = (i, L)
    return s[start:start + max_length]

def longest_palindrome(s):
    if len(s) == 0:
        return ''
    max_length = 1
    start_index = 0
    for i in range(len(s)):
        low, high = (i, i)
        while low >= 0 and high < len(s) and (s[low] == s[high]):
            if high - low + 1 > max_length:
                start_index = low
                max_length = high - low + 1
            low -= 1
            high += 1
        low, high = (i, i + 1)
        while low >= 0 and high < len(s) and (s[low] == s[high]):
            if high - low + 1 > max_length:
                start_index = low + 1
                max_length = high - low + 1
            low -= 1
            high += 1
    return s[start_index:start_index + max_length]

