def roman_to_int(s):
    if not s:
        raise ValueError('Empty string is not allowed')
    valid = {'I', 'V', 'X', 'L', 'C', 'D', 'M'}
    if not all((c in valid for c in s)):
        raise ValueError('Input contains invalid characters')
    symbols_count = {c: s.count(c) for c in valid}
    for symbol in ['IV', 'IX', 'XL', 'XC', 'CD', 'CM']:
        if symbol in s and symbols_count[symbol[0]] >= 3 or symbols_count[symbol[1]] >= 3:
            raise ValueError('Invalid numeral structure')
    total = 0
    for i in range(len(s) - 1, -1, -1):
        current = s[i]
        if current in ['I', 'X', 'C'] and (i < len(s) - 1 and s[i + 1] not in [current[:-1], 'V', 'L', 'D']) or current in ['V', 'L', 'D']:
            next_symbol = s[i + 1] if i < len(s) - 1 else None
            if current in ['X', 'C'] and next_symbol == current[:-1]:
                total += sum([5 * symbols_count[current], 10 * symbols_count[next_symbol]])
            elif current in ['I', 'V', 'L'] and next_symbol in [current[:-1], 'D']:
                total += sum([4 * symbols_count[current], 5 * symbols_count[next_symbol]])
            else:
                total += symbols_count[current]
        else:
            total += symbols_count[current]
    return total

def roman_to_int(s):
    valid = {'I', 'V', 'X', 'L', 'C', 'D', 'M'}
    subtractive = {('IV', 4), ('IX', 9), ('XL', 40), ('XC', 90), ('CD', 400), ('CM', 900)}
    if not s:
        raise ValueError('Empty string')
    for char in s:
        if char not in valid:
            raise ValueError(f"Invalid character '{char}'")
    result = 0
    i = len(s) - 1
    while i >= 0:
        char, num = (None, 0)
        for c, n in subtractive:
            if s[i:i + len(c)] == c:
                char, num = (c[0], num)
                break
        if not char:
            char = s[i]
            if char in ('I', 'X', 'C'):
                if s[i - 3:i + 1].count(char) > 3:
                    raise ValueError(f"Repetition error for '{char}'")
            elif char in ('V', 'L', 'D'):
                if s[i - 1] == char:
                    raise ValueError(f"Repeat error for '{char}'")
        num = int(num)
        result += num * valid.index(char)
        i -= len(char)
    return result

def roman_to_int(s):
    valid_symbols = {'I', 'V', 'X', 'L', 'C', 'D', 'M'}
    numerals = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    max_repeat = 3
    if not s:
        raise ValueError('Empty string is not allowed.')
    for symbol in s:
        if symbol not in valid_symbols:
            raise ValueError(f'Invalid Roman numeral symbol: {symbol}')
        if symbol in {'I', 'X', 'C', 'M'} and s.count(symbol) > max_repeat:
            raise ValueError(f"Too many consecutive repetitions of '{symbol}'.")
        if symbol in ('V', 'L', 'D') and s.count(symbol) > 1:
            raise ValueError(f"Repeated occurrence of '{symbol}' is not allowed.")
        for pair in numerals:
            if symbol + pair[0] in s and pair[1] + symbol in s:
                raise ValueError(f'Invalid Roman numeral combination: {symbol}{pair[0]} and {pair[1]}{symbol}')
    roman_value = sum([s.count(symbol) for symbol in valid_symbols])
    for pair in numerals:
        roman_value -= numerals[pair] * (s.count(pair[0]) if pair[0] not in s[1:] else s.count(pair[1]) - 1)
    return roman_value

