            stack.append(seq)
        return decode_helper(stack, seq)
    return decode_helper([], s) if s else ''

def decode_string(s):
    result = ''
    i = 0
    while i < len(s):
        count = 1
        if i + 1 < len(s) and s[i] == '[':
