def wildcard_match(s, p):

    def matchstar(ss, pp, i=0):
        while i < len(pp) and pp[i] == '*':
            i += 1
        if i >= len(pp):
            return True if not ss else False
        if i > 0 and pp[i - 1] == "'":
            return matchstar(ss, pp, i + 1)
        return (ss and ss[0] == pp[i]) and matchstar(ss[1:], pp[i + 1:], 0)
    u = len(s)
    v = len(p)
    if not v:
        return not u
    for i in range(min(u, v)):
        if s[i] != p[i] and (p[i] != '?' or s[i] != p[i]):
            break
    if i < min(u, v):
        return False
    return matchstar(s[i:], p[i:])

def word_frequency(text):
    words = text.lower().split()
    freq_dict = {}
    for word in words:
        word = ''.join((c for c in word if c.isalnum()))
        if word:
            freq_dict[word] = freq_dict.get(word, 0) + 1
    return freq_dict

def word_frequency(text):
    words = text.strip().replace('  ', ' ').lower().split()
    freq_dict = {}
    for word in words:
        if word not in freq_dict:
            freq_dict[word] = 1
        else:
            freq_dict[word] += 1
    return freq_dict

def word_frequency(text):
    words = text.lower().split()
    freq_dict = {}
    for word in words:
        word = ''.join(filter(str.isalnum, word))
        if word:
            freq_dict[word] = freq_dict.get(word, 0) + 1
    return freq_dict

import re

def word_frequency(text):
    words = re.findall('\\w+', text)
    freq_dict = {}
    for word in words:
        if word in freq_dict:
            freq_dict[word] += 1
        else:
            freq_dict[word] = 1
    return freq_dict

def word_frequency(text):
    text = re.sub('[^\\w\\s]', '', text).lower()
    words = text.split()
    freq_dict = {}
    for word in set(words):
        if word in freq_dict:
            freq_dict[word] += 1
        else:
            freq_dict[word] = 1
    return freq_dict

def word_frequency(text):
    text = text.lower()
    words = text.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count

import re

def validate_password(password):
    if len(password) < 8:
        return False
    if not re.search('[A-Z]', password) or not re.search('[a-z]', password) or (not re.search('\\d', password)):
        return False
    if not re.search('[\\W]', password):
        return False
    return True

