import re

def validate_password(password):
    if len(password) < 8:
        return False
    lowercase = re.search('[a-z]', password)
    uppercase = re.search('[A-Z]', password)
    digit = re.search('[0-9]', password)
    special_char = re.search('[!@#$%^&*(),.?/:;{}|<>]', password)
    if not (lowercase and uppercase and digit and special_char):
        return False
    for char in password:
        if char.isalpha() or char.isdigit() or char.isalnum(char) or char.isspace():
            continue
        count = password.count(char)
        if count < 2:
            return False
    return True

import re

def validate_password(password):
    if len(password) < 8:
        return False
    has_uppercase = bool(re.search('[A-Z]', password))
    has_lowercase = bool(re.search('[a-z]', password))
    has_digit = bool(re.search('\\d', password))
    has_special = bool(re.search('[!@#$%^&*()]', password))
    if not (has_uppercase and has_lowercase and has_digit and has_special):
        return False
    if any((char == next_char for char, next_char in zip(password, password[1:]))):
        return False
    return True

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals:
        last_merged = merged[-1]
        if last_merged[1] >= current[0]:
            last_merged[1] = max(last_merged[1], current[1])
        else:
            merged.append(current)
    return merged

