def roman_to_int(s):
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError('Input cannot be an empty string.')
    prev_value = -1
    total = 0
    for char in s:
        if char not in roman_values:
            raise ValueError(f'Invalid Roman numeral: {char}')
        current_value = roman_values[char]
        if prev_value < current_value:
            total += current_value - 2 * prev_value
        else:
            total += current_value
        prev_value = current_value
    return total

def roman_to_int(s):
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError('Input cannot be an empty string.')
    if any((char not in roman_values for char in s)):
        raise ValueError(f"Invalid Roman numeral: '{s}' contains unsupported characters.")
    result = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_values[char]
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value
    return result

def roman_to_int(s):
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError('Input string cannot be empty')
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_values.get(char, None)
        if value is not None and prev_value > 0 and (value < prev_value):
            raise ValueError('Invalid Roman numeral')
        if value is not None and value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def roman_to_int(s: str) -> int:
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    for char in s:
        if char not in roman_values:
            raise ValueError('Invalid Roman numeral: contains invalid characters')
    result = 0
    prev_value = 0
    for char in reversed(s):
        curr_value = roman_values[char]
        if curr_value < prev_value:
            result -= curr_value
        else:
            result += curr_value
        prev_value = curr_value
    return result

def roman_to_int(s: str) -> int:
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s or not all((c in roman_values for c in s)):
        raise ValueError('Invalid Roman numeral')
    result = 0
    prev_value = 0
    for i in range(len(s) - 1, -1, -1):
        current_value = roman_values[s[i]]
        if current_value >= prev_value:
            result += current_value
        else:
            result -= current_value
        prev_value = current_value
    return result

def roman_to_int(s: str) -> int:
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError('Input cannot be an empty string')
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_values.get(char)
        if value is None:
            raise ValueError(f'Invalid character: {char}')
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def roman_to_int(s: str) -> int:
    if s == '':
        raise ValueError
    numeral_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    prev_value = 0
    total = 0
    for char in s:
        if char not in numeral_map:
            raise ValueError
        value = numeral_map[char]
        if prev_value and (char == 'V' or char == 'X') and (prev_value * 5 != value):
            raise ValueError
        elif prev_value and (char == 'L' or char == 'C') and (prev_value * 50 != value):
            raise ValueError
        elif prev_value and (char == 'D' or char == 'M') and (prev_value * 500 != value):
            raise ValueError
        if prev_value and value > prev_value:
            total += value - 2 * prev_value
        else:
            total += value
        prev_value = value
    for i in range(len(s) - 1):
        if s[i] == 'I' and s[i + 1] not in ['V', 'X'] or (s[i] == 'X' and s[i + 1] not in ['L', 'C']) or (s[i] == 'C' and s[i + 1] not in ['D', 'M']):
            raise ValueError
    if prev_value * 4 > total:
        raise ValueError
    return total

def roman_to_int(s: str) -> int:
    if s == '':
        raise ValueError
    numeral_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    prev_value = 0
    total = 0
    for char in s:
        if char not in numeral_map:
            raise ValueError
        value = numeral_map[char]
        if prev_value == 0 or value <= prev_value:
            if prev_value * 10 < value:
                raise ValueError
            total += value
        elif prev_value * 5 < value < prev_value * 10:
            if (char, prev_value) not in [('IV', 1), ('IX', 1), ('XL', 10), ('XC', 10), ('CD', 100), ('CM', 100)]:
                raise ValueError
            total += value - 2 * prev_value
        else:
            raise ValueError
        prev_value = value
    return total

def roman_to_int(s: str) -> int:
    if s == '':
        raise ValueError
    numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    prev_value = 0
    total = 0
    for char in s[::-1]:
        value = numerals.get(char)
        if value is None:
            raise ValueError
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    allowed_subtracts = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}
    subtracts = set()
    for i in range(len(s) - 1):
        pair = s[i:i + 2]
        if pair in allowed_subtracts:
            continue
        else:
            raise ValueError
    if total > numerals['M'] * 3 or total < 0:
        raise ValueError
    return total

def is_balanced(s: str) -> bool:
    bracket_map = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return len(stack) == 0

