        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(int(left / right))

    def precedence(c):
        if c == '+' or c == '-':
            return 1
        if c == '*' or c == '/':
            return 2
        return 0
    operators = []
    values = []
    i = 0
    while i < len(expr):
        expr = expr.replace(' ', '')
        ch = expr[i]
        if ch.isdigit():
            j = i + 1
            while j < len(expr) and expr[j].isdigit():
                j += 1
            values.append(int(expr[i:j]))
            i = j - 1
        elif ch in '+-*/':
            while operators and operators[-1] != '(' and (precedence(operators[-1]) >= precedence(ch)):
                apply_op(operators, values)
            operators.append(ch)
        elif ch == '(':
            operators.append(ch)
        elif ch == ')':
            while operators[-1] != '(':
                apply_op(operators, values)
            operators.pop()
        i += 1
    while operators:
        apply_op(operators, values)
    return values[0]

def evaluate(expr: str) -> int:
    import re
    expr = expr.replace(' ', '')
    if not re.match('^[0-9+\\-*/()]*$', expr):
        raise ValueError('Invalid expression')

    def precedence(op: str) -> int:
        if op in '+-':
            return 1
        if op in '*/':
            return 2
        return 0

    def apply_operation(operands, operators):
        right = operands.pop()
        left = operands.pop()
        op = operators.pop()
        if op == '+':
            operands.append(left + right)
        elif op == '-':
            operands.append(left - right)
        elif op == '*':
            operands.append(left * right)
        elif op == '/':
            operands.append(int(left / right))

    def eval_expr(expr: str) -> int:
        stack = []
        num = ''
        operators = []
        for char in expr:
            if char.isdigit():
                num += char
            else:
                if num:
                    stack.append(int(num))
                    num = ''
                if char == '(':
                    stack.append(char)
                elif char == ')':
                    while stack and stack[-1] != '(':
                        apply_operation(stack, operators)
                    stack.pop()
                else:
                    while (stack and stack[-1] != '(') and precedence(operators) >= precedence(char):
                        apply_operation(stack, operators)
                    operators.append(char)
        if num:
            stack.append(int(num))
        while stack:
            apply_operation(stack, operators)
        return stack[0]
    return eval_expr(expr)

def evaluate(expr: str) -> int:
    import re
    expr = expr.replace(' ', '')

    def calculate(op1, operator, op2):
        if operator == '+':
            return op1 + op2
        elif operator == '-':
            return op1 - op2
        elif operator == '*':
            return op1 * op2
        elif operator == '/':
            return int(op1 / op2)

    def shunting_yard(expr):
        operators = []
        operands = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        token_pattern = re.compile('(\\d+|[-+*/()])')
        for token in token_pattern.findall(expr):
            if token.isdigit():
                operands.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    op2 = operands.pop()
                    op1 = operands.pop()
                    operator = operators.pop()
                    operands.append(calculate(op1, operator, op2))
                if operators and operators[-1] == '(':
                    operators.pop()
            else:
                while operators and operators[-1] != '(' and (precedence[operators[-1]] >= precedence[token]):
                    op2 = operands.pop()
                    op1 = operands.pop()
                    operator = operators.pop()
                    operands.append(calculate(op1, operator, op2))
                operators.append(token)
        while operators:
            op2 = operands.pop()
            op1 = operands.pop()
            operator = operators.pop()
            operands.append(calculate(op1, operator, op2))
        return operands[0]
    try:
        result = shunting_yard(expr)
        return int(result)
    except (IndexError, ValueError):
        raise ValueError('Invalid expression')

