def evaluate(expr: str) -> int:
    expr = expr.replace(' ', '')

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))

    def greater_precedence(op1, op2):
        return op1 in '+-' and op2 in '*/' or (op1 in '*/' and op2 in '*/')
    operators = []
    values = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            values.append(int(expr[i:j]))
            i = j - 1
        elif expr[i] in '+-*/':
            while operators and operators[-1] != '(' and greater_precedence(operators[-1], expr[i]):
                apply_operator(operators, values)
            operators.append(expr[i])
        elif expr[i] == '(':
            operators.append(expr[i])
        elif expr[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        i += 1
    while operators:
        apply_operator(operators, values)
    return values[0]

def evaluate(expr: str) -> int:

    def apply_op(op, reg1, reg2):
        if op == '+':
            return reg1 + reg2
        elif op == '-':
            return reg1 - reg2
        elif op == '*':
            return reg1 * reg2
        elif op == '/':
            return int(reg1 / reg2)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def operate(stack, ops_stack):
        op = ops_stack.pop()
        right = stack.pop()
        left = stack.pop()
        result = apply_op(op, left, right)
        stack.append(result)
    expr = expr.replace(' ', '')
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            start = i
            while i + 1 < len(expr) and expr[i + 1].isdigit():
                i += 1
            tokens.append(int(expr[start:i + 1]))
            i -= 1
        elif expr[i] in ('+', '-', '*', '/'):
            if expr[i] == '(':
                count = 0
                for j in range(i + 1, len(expr)):
                    if expr[j] == '(':
                        count += 1
                    if expr[j] == ')':
                        count -= 1
                    if count == 0:
                        break
                tokens.append(evaluate(expr[i + 1:j]))
            else:
                while ops_stack and precedence(ops_stack[-1]) >= precedence(expr[i]):
                    operate(stack, ops_stack)
                ops_stack.append(expr[i])
        i += 1
    for op in reversed(ops_stack):
        operate(stack, [op])
    return stack[0]

def evaluate(expr: str) -> int:
    import tokenize
    from io import BytesIO

    def read_token(tokens):
        return next(tokens)

    def parse_expression(tokens):
        stack = []
        current = None
        while True:
            try:
                token = read_token(tokens)
                if token.exact_type == tokenize.NUMBER:
                    value = int(token.string)
                    if current is None:
                        current = value
                    else:
                        last_op = stack.pop()
                        if last_op == '+':
                            current += value
                        elif last_op == '-':
                            current -= value
                        elif last_op == '*':
                            current *= value
                        elif last_op == '/':
                            current //= value
                elif token.exact_type in (tokenize.OP, tokenize.NEWLINE):
                    if token.string == '(':
                        subexpr = parse_expression(tokens)
                        if stack and stack[-1] == '/':
                            current //= subexpr
                            stack.pop()
                        else:
                            current = subexpr
                    elif token.string == ')':
                        return current
                    elif token.string in '+-*/':
                        stack.append(token.string)
                else:
                    raise ValueError
            except StopIteration:
                break
    try:
        tokens = tokenize.generate_tokens(BytesIO(expr.encode()).readline)
        result = parse_expression(tokens)
    except (tokenize.TokenError, StopIteration):
        raise ValueError
    return result

def evaluate(expr: str) -> int:
    import re

    def tokenize(s):
        return [t for t in re.findall('\\d+|[-+*/()]', s)]
    tokens = tokenize(expr.replace(' ', ''))
    stack, num, sign = ([], 0, '+')
    ops = {'+': lambda x: x, '-': lambda x: -x, '*': lambda x: x * num, '/': lambda x: int(x / num)}
    for i, token in enumerate(tokens + ['']):
        if token.isdigit():
            num = int(token)
        elif token in '+-*/':
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(stack.pop() / num))
            sign = token
            num = 0
        elif token == '(':
            j = 1
            for k in range(i + 1, len(tokens)):
                if tokens[k] == ')':
                    j -= 1
                elif tokens[k] == '(':
                    j += 1
                if not j:
                    return stack.append(evaluate(''.join(tokens[i + 1:k]))) or evaluate(''.join(tokens[k + 1:])) + sum(stack)
        if i == len(tokens) - 1 and sign in ops:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            else:
                stack.append(int(stack.pop() / num))
    return sum(stack)

