            while stack and stack[-1] != '(':
                apply_operation(operands, stack)
            stack.pop()
        else:
            while stack and stack[-1] != '(' and (precedence(stack[-1]) >= precedence(token)):
                apply_operation(operands, stack)
            stack.append(token)
    while stack:
        apply_operation(operands, stack)
    return operands[0]

