def decode_string(s: str) -> str:
    stack, num, res = ([], 0, '')
    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char == '[':
            stack.append((res, num))
            res, num = ('', 0)
        elif char.isalpha() or char == ']':
            res += char
            if char == ']':
                prev_res, count = stack.pop()
                res = prev_res + count * res
    return res if not stack else ''

def decode_string(s: str) -> str:
    if not s or len(s) == 0:
        raise ValueError('Invalid input')
    stack = []
    current_num = ''
    current_str = ''
    num = 0
    for char in s:
        if char.isdigit():
            current_num += char
        elif char.isalpha():
            current_str += char
        elif char == '[':
            stack.append((current_str, num))
            current_str, num = ('', 0)
        elif char == ']':
            if not stack:
                raise ValueError('Invalid input')
            prev_str, prev_num = stack.pop()
            current_str = prev_str + current_num * prev_num + current_str
            num = 0
    if stack:
        raise ValueError('Invalid input')
    return current_str

def remove_k_digits(num: str, k: int) -> str:
    stack = []
    for digit in num:
        while k > 0 and stack and (stack[-1] > digit):
            stack.pop()
