    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = match(i, j) and dp[i - 1][j - 1]
    return dp[m][n]

def wildcard_match(s: str, p: str) -> bool:

    def match(i: int, j: int) -> bool:
        return i < len(s) and (s[i] == p[j] or p[j] == '?')
    m, n = (len(s), len(p))
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = match(i, j) and dp[i - 1][j - 1]
    return dp[m][n]

import string

def word_frequency(text):
    translator = str.maketrans('', '', string.punctuation)
    normalized_text = text.lower().translate(translator)
    words = normalized_text.split()
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return word_counts

def word_frequency(text):
    text = text.lower()
