def validate_password(password):
    if len(password) < 8:
        return False
    has_uppercase = any((char.isupper() for char in password))
    has_lowercase = any((char.islower() for char in password))
    has_digit = any((char.isdigit() for char in password))
    has_special_char = any((char in '!@#$%^&*()-_=+[]{}|;:,.<>?/~' for char in password))
    return has_uppercase and has_lowercase and has_digit and (has_special_char if 'special_chars' in locals() else True)

import re

def validate_password(password):
    if len(password) < 8:
        return False
    if not re.search('[0-9]', password):
        return False
    if not re.search('[!@#$%^&*(),.?":{}|<>]', password):
        return False
    return True

import re

def validate_password(password):
    if len(password) < 8:
        return False
    has_uppercase = re.search('[A-Z]', password)
    has_lowercase = re.search('[a-z]', password)
    has_digit = re.search('\\d', password)
    has_special_char = re.search('[^A-Za-z0-9]', password)
    return bool(has_uppercase and has_lowercase and has_digit and has_special_char)

import re

def validate_password(password):
    if len(password) < 8:
        return False
    pattern = '^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[@$!%*#?&])[A-Za-z\\d@$!%*#?&]{8,}$'
    if re.match(pattern, password):
        return True
    else:
        return False

import re

def validate_password(password):
    conditions = [len(password) >= 8, bool(re.search('[a-z]', password)), bool(re.search('[A-Z]', password)), bool(re.search('\\d', password)), bool(re.search('[!@#$%^&*(),.?":{}|<>]', password))]
    if all(conditions):
        return True
    else:
        return False

import re

def validate_password(password):
    MIN_LENGTH = 8
    if len(password) < MIN_LENGTH:
        return False
    if not re.search('[0-9]', password):
        return False
    if not re.search('[A-Z]', password):
        return False
    if not re.search('[a-z]', password):
        return False
    if not re.search('[^A-Za-z0-9]', password):
        return False
    return True

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for current_start, current_end in intervals[1:]:
        last_end = merged[-1][1]
        if current_start <= last_end:
            merged[-1][1] = max(last_end, current_end)
        else:
            merged.append([current_start, current_end])
    return merged

